import { useRef, useState } from 'react';
import gsap from 'gsap';
import { useGSAP } from '@gsap/react';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { Flip } from 'gsap/Flip';
import { PORTFOLIO_DATA } from '../data';

gsap.registerPlugin(ScrollTrigger, Flip);

const FILTERS = ['All', 'Product Design', 'UX/UI Design', 'Graphic Design'];

export default function Work() {
  const root = useRef(null);
  const [filter, setFilter] = useState('All');
  const flipState = useRef(null);

  const filtered =
    filter === 'All' ? PORTFOLIO_DATA.projects : PORTFOLIO_DATA.projects.filter((p) => p.category === filter);

  const { contextSafe } = useGSAP(
    () => {
      const mm = gsap.matchMedia();

      // Flip re-entry after filter change
      if (flipState.current) {
        Flip.from(flipState.current, {
          duration: 0.6,
          ease: 'power3.inOut',
          scale: true,
          absolute: false,
          stagger: 0.05,
          overwrite: 'auto',
        });
        flipState.current = null;
      }

      // card entrance (vertical fallback + initial) — scoped
      gsap.utils.toArray('.work-card', root.current).forEach((card) => {
        gsap.fromTo(
          card,
          { y: 40, autoAlpha: 0 },
          {
            y: 0,
            autoAlpha: 1,
            duration: 0.7,
            ease: 'power3.out',
            scrollTrigger: { trigger: card, start: 'top 92%', toggleActions: 'play none none reverse' },
          }
        );
      });

      // Desktop: fake horizontal scroll — ease none required
      mm.add('(min-width: 768px)', () => {
        const track = root.current?.querySelector('.work-track');
        const pinWrap = root.current?.querySelector('.work-pin');
        if (!track || !pinWrap) return;

        const getDist = () => Math.max(0, track.scrollWidth - window.innerWidth);
        const scrollTween = gsap.to(track, {
          x: () => -getDist(),
          ease: 'none',
          scrollTrigger: {
            trigger: root.current,
            start: 'top top',
            end: () => `+=${getDist()}`,
            pin: true,
            scrub: 1,
            invalidateOnRefresh: true,
            refreshPriority: 1,
          },
        });

        // inner image drift tied to horizontal progress
        gsap.utils.toArray('.work-card img', root.current).forEach((img) => {
          gsap.fromTo(
            img,
            { xPercent: -6 },
            {
              xPercent: 6,
              ease: 'none',
              scrollTrigger: { containerAnimation: scrollTween, trigger: img.closest('.work-card'), start: 'left right', end: 'right left', scrub: true },
            }
          );
        });

        gsap.fromTo(
          '.work-progress',
          { scaleX: 0 },
          {
            scaleX: 1,
            ease: 'none',
            scrollTrigger: {
              trigger: root.current,
              start: 'top top',
              end: () => `+=${getDist()}`,
              scrub: 0.3,
            },
          }
        );

        return () => {
          scrollTween.scrollTrigger?.kill();
          scrollTween.kill();
        };
      });

      return () => mm.revert();
    },
    { scope: root, dependencies: [filter], revertOnUpdate: true }
  );

  const onFilter = contextSafe((f) => {
    if (f === filter) return;
    flipState.current = Flip.getState('.work-card');
    setFilter(f);
    // recalc pins after DOM settles
    requestAnimationFrame(() => ScrollTrigger.refresh());
  });

  const onCardEnter = contextSafe((e) => {
    gsap.to(e.currentTarget.querySelector('img'), { scale: 1.06, duration: 0.6, ease: 'power2.out', overwrite: 'auto' });
  });
  const onCardLeave = contextSafe((e) => {
    gsap.to(e.currentTarget.querySelector('img'), { scale: 1, duration: 0.6, ease: 'power2.out', overwrite: 'auto' });
  });

  return (
    <section ref={root} id="work" className="bg-[#1a1a1a] border-t border-white/20 relative">
      <div className="work-pin md:h-screen flex flex-col justify-center overflow-hidden py-16 md:py-0">
        <div className="px-6 md:px-12 pt-4 pb-8 flex flex-col md:flex-row md:items-end justify-between gap-6">
          <h2 className="font-syne text-5xl md:text-[6vw] font-bold leading-none text-white tracking-tighter">
            SELECTED <span className="text-transparent stroke-text-white">WORKS</span>
          </h2>
          <div className="flex flex-wrap gap-2">
            {FILTERS.map((f) => (
              <button
                key={f}
                onClick={() => onFilter(f)}
                data-magnetic
                className={`px-4 py-1.5 rounded-full text-xs font-mono uppercase border transition-colors ${
                  filter === f ? 'bg-[#FF3333] border-[#FF3333] text-white' : 'border-white/20 text-white/60 hover:border-white hover:text-white'
                }`}
              >
                {f}
              </button>
            ))}
          </div>
        </div>

        <div className="work-track flex flex-col md:flex-row gap-6 px-6 md:px-12 will-transform">
          {filtered.map((p) => (
            <a
              key={p.id}
              href={p.link}
              target={p.link ? '_blank' : undefined}
              rel="noopener noreferrer"
              onMouseEnter={onCardEnter}
              onMouseLeave={onCardLeave}
              data-magnetic
              className="work-card group relative shrink-0 w-full md:w-[44vw] lg:w-[38vw] border border-white/15 rounded-2xl overflow-hidden bg-white/[0.03] hover:border-[#FF3333]/60 transition-colors will-fade"
            >
              <div className="relative h-[46vh] md:h-[48vh] overflow-hidden">
                <img src={p.imageUrl} alt={p.title} loading="lazy" className="w-full h-full object-cover scale-100 will-transform" />
                <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-transparent to-transparent" />
                <span className="absolute top-4 left-4 font-mono text-[11px] tracking-[0.2em] text-[#FF3333] bg-black/60 px-3 py-1 rounded-full">
                  {p.id} / {p.category.toUpperCase()}
                </span>
              </div>
              <div className="p-6 md:p-8">
                <h3 className="font-syne text-3xl md:text-5xl font-bold uppercase leading-[0.9] text-white">
                  {p.title.split(' ')[0]} <br />
                  <span className="text-transparent stroke-text-white">{p.subtitle}</span>
                </h3>
                <p className="text-gray-400 mt-4 line-clamp-2 leading-relaxed">{p.description}</p>
                <div className="flex flex-wrap gap-2 mt-5">
                  {p.tags.map((t) => (
                    <span key={t} className="border border-white/20 px-3 py-1 text-[11px] font-mono uppercase text-gray-300 rounded-full">
                      {t}
                    </span>
                  ))}
                </div>
              </div>
            </a>
          ))}
        </div>

        <div className="px-6 md:px-12 mt-8">
          <div className="h-[2px] bg-white/10 overflow-hidden rounded">
            <div className="work-progress h-full bg-[#FF3333] origin-left scale-x-0 w-full" />
          </div>
          <p className="font-mono text-[11px] uppercase tracking-[0.25em] text-white/40 mt-3 hidden md:block">
            Scroll to travel horizontally — {filtered.length} case{filtered.length > 1 ? 's' : ''}
          </p>
        </div>
      </div>
    </section>
  );
}
